-- CalculixHub: remove the opening Community Solutions threads.
--
-- GENERATED by scripts/community-seed/build.mjs.
--
-- Deletes every seed account (email ending @community-seed.calculixhub.invalid) and, by
-- cascade, its profile, posts, comments, reactions, follows and notifications.
-- Comments that learners left on seed posts go with those posts. Learners'
-- own posts are untouched.
begin;

select
  (select count(*) from auth.users where email like '%@community-seed.calculixhub.invalid') as seed_accounts,
  (select count(*) from public.posts where author_id in (select id from auth.users where email like '%@community-seed.calculixhub.invalid')) as seed_posts;

delete from auth.users where email like '%@community-seed.calculixhub.invalid';

commit;
